<script>
(function(){const sidebar=document.getElementById('sidebar');document.getElementById('menuBtn')?.addEventListener('click',()=>sidebar?.classList.toggle('open'));document.getElementById('themeToggleBtn')?.addEventListener('click',()=>document.body.classList.toggle('light'));const profileBtn=document.getElementById('profileMenuBtn'),drop=document.getElementById('profileDropdown');if(profileBtn&&drop)profileBtn.addEventListener('click',e=>{e.stopPropagation();drop.classList.toggle('open')});document.addEventListener('click',e=>{if(drop&&!drop.parentElement.contains(e.target))drop.classList.remove('open')});window.openProfileModal=function(){document.getElementById('profileModalOverlay')?.classList.add('open')};document.getElementById('profileModalCloseBtn')?.addEventListener('click',()=>document.getElementById('profileModalOverlay')?.classList.remove('open'));['monitorGroup','reportGroup','analysisGroup'].forEach(id=>{const g=document.getElementById(id),b=g?.querySelector('.side-nav-group-title');b?.addEventListener('click',()=>g.classList.toggle('open'))});function showSection(id,link){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));const el=document.getElementById(id);if(el)el.classList.add('active');document.querySelectorAll('.side-sub-link,.side-link').forEach(a=>a.classList.remove('active'));if(link)link.classList.add('active');sidebar?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('.side-link[href^="#"],.side-sub-link[href^="#"],.card-link[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);if(document.getElementById(id)){e.preventDefault();showSection(id,a)}}));window.openReportDetail=function(button){const modal=document.getElementById('reportDetailModal');document.getElementById('detailPengirim').textContent=button.dataset.pengirim||'-';document.getElementById('detailTujuan').textContent=button.dataset.tujuan||'-';document.getElementById('detailPerihal').textContent=button.dataset.perihal||'-';document.getElementById('detailPrioritas').textContent=button.dataset.prioritas||'-';document.getElementById('detailProyek').textContent=button.dataset.proyek||'-';document.getElementById('detailTanggal').textContent=button.dataset.tanggal||'-';document.getElementById('detailDeskripsi').textContent=button.dataset.deskripsi||'-';const lampiran=button.dataset.lampiran||'',wrap=document.getElementById('detailLampiranWrap'),link=document.getElementById('detailLampiran');if(lampiran){link.href=lampiran;wrap.style.display='block'}else{wrap.style.display='none'}modal?.classList.add('open')};document.getElementById('reportDetailClose')?.addEventListener('click',()=>document.getElementById('reportDetailModal')?.classList.remove('open'));document.getElementById('reportDetailModal')?.addEventListener('click',e=>{if(e.target.id==='reportDetailModal')e.currentTarget.classList.remove('open')});
const satlakLabels=@json($monitoringPimpinanSatlak->pluck('kode')->values());const satlakTotals=@json($monitoringPimpinanSatlak->pluck('total')->values());const statusData={menunggu:{{ $laporanPimpinanSatlak->filter(fn($l)=>$l->status==='Menunggu')->count() }},revisi:{{ $laporanPimpinanSatlak->filter(fn($l)=>str_contains(strtolower((string)$l->status),'revisi'))->count() }},disetujui:{{ $laporanPimpinanSatlak->filter(fn($l)=>str_contains(strtolower((string)$l->status),'setuj') || str_contains(strtolower((string)$l->status),'diterima'))->count() }},ditolak:{{ $laporanPimpinanSatlak->filter(fn($l)=>str_contains(strtolower((string)$l->status),'tolak'))->count() }}};function makeStatusChart(id){const el=document.getElementById(id);if(!el||typeof Chart==='undefined')return;new Chart(el,{type:'doughnut',data:{labels:['Menunggu','Revisi','Disetujui','Ditolak'],datasets:[{data:[statusData.menunggu,statusData.revisi,statusData.disetujui,statusData.ditolak],backgroundColor:['#d4a017','#e2b93b','#16834b','#c83b3b'],borderColor:'#fff',borderWidth:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:12,padding:14,font:{size:11}}}}}})}function makeSatlakChart(id){const el=document.getElementById(id);if(!el||typeof Chart==='undefined')return;new Chart(el,{type:'bar',data:{labels:satlakLabels,datasets:[{label:'Jumlah laporan',data:satlakTotals,backgroundColor:'#c97a00',borderRadius:7,maxBarThickness:42}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#e9edf2'}},x:{grid:{display:false}}},plugins:{legend:{display:false}}}})}makeStatusChart('statusChart');makeSatlakChart('satlakChart');makeStatusChart('statusChartAnalysis');makeSatlakChart('satlakChartAnalysis');})();
</script>
